name: Deploy testnet

# Manual only. Refuses mainnet / live networks.
on:
  workflow_dispatch:
    inputs:
      network:
        description: "Hardhat network (testnet only)"
        required: true
        type: choice
        options:
          - base-sepolia
      run_smoke:
        description: "Run smoke-base-sepolia.js after deploy"
        type: boolean
        default: true

jobs:
  deploy:
    runs-on: ubuntu-latest
    environment: testnet
    steps:
      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4
      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4
        with:
          node-version: "20"
          cache: npm
      - run: npm ci
      - name: Guard — refuse live/mainnet
        run: |
          case "${{ inputs.network }}" in
            base-sepolia) echo "ok testnet ${{ inputs.network }}" ;;
            *) echo "Refusing network ${{ inputs.network }}"; exit 1 ;;
          esac
      - name: Deploy
        env:
          PRIVATE_KEY: ${{ secrets.TESTNET_DEPLOYER_PRIVATE_KEY }}
          BASE_SEPOLIA_RPC: ${{ secrets.BASE_SEPOLIA_RPC }}
          ETHERSCAN_API_KEY: ${{ secrets.ETHERSCAN_API_KEY }}
          BASESCAN_API_KEY: ${{ secrets.BASESCAN_API_KEY }}
          BASE_SEPOLIA_ADMIN_ADDRESS: ${{ secrets.BASE_SEPOLIA_ADMIN_ADDRESS }}
          BASE_SEPOLIA_AGGREGATOR_ADDRESS: ${{ secrets.BASE_SEPOLIA_AGGREGATOR_ADDRESS }}
          BASE_SEPOLIA_TREASURY_ADDRESS: ${{ secrets.BASE_SEPOLIA_TREASURY_ADDRESS }}
          BASE_SEPOLIA_FEE_RECIPIENT_ADDRESS: ${{ secrets.BASE_SEPOLIA_FEE_RECIPIENT_ADDRESS }}
          REQUIRE_VERIFY: "1"
          REQUIRE_WIRED: "1"
        run: npx hardhat run scripts/deploy.js --network ${{ inputs.network }}
      - name: Upload deployment artifact
        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4
        with:
          name: deployment-${{ inputs.network }}
          path: deployments/*.latest.json
      - name: Verify (idempotent re-run)
        env:
          PRIVATE_KEY: ${{ secrets.TESTNET_DEPLOYER_PRIVATE_KEY }}
          BASE_SEPOLIA_RPC: ${{ secrets.BASE_SEPOLIA_RPC }}
          ETHERSCAN_API_KEY: ${{ secrets.ETHERSCAN_API_KEY }}
          BASESCAN_API_KEY: ${{ secrets.BASESCAN_API_KEY }}
          DEPLOYMENT_FILE: deployments/84532.base-sepolia.latest.json
        run: npx hardhat run scripts/verify-deployment.js --network ${{ inputs.network }}
      - name: Smoke
        if: ${{ inputs.run_smoke }}
        env:
          PRIVATE_KEY: ${{ secrets.TESTNET_DEPLOYER_PRIVATE_KEY }}
          BASE_SEPOLIA_RPC: ${{ secrets.BASE_SEPOLIA_RPC }}
          DEPLOYMENT_FILE: deployments/84532.base-sepolia.latest.json
          SMOKE_TOKEN: "0x036CbD53842c5426634e7929541eC2318f3dCF7e"
        run: npx hardhat run scripts/smoke-base-sepolia.js --network base-sepolia
      - name: Post-deploy check
        env:
          PRIVATE_KEY: ${{ secrets.TESTNET_DEPLOYER_PRIVATE_KEY }}
          BASE_SEPOLIA_RPC: ${{ secrets.BASE_SEPOLIA_RPC }}
        run: npx hardhat run scripts/post-deploy-check.js --network ${{ inputs.network }}

