/**
 * Fresh deployment of the ElementFlow v2 stack.
 *
 *   ProviderRegistry (UUPS)  -- routes providerId -> adapter
 *   ElementFlowOrderManager (UUPS) -- escrow, settlement, fees
 *   TreasuryPool (UUPS)      -- in-house liquidity, registered as the default adapter
 *
 * Use `scripts/upgrade-v1-to-v2.js` instead when a v1 proxy already exists on the target
 * network — that path preserves the live address and its pending orders.
 *
 *   npx hardhat run scripts/deploy.js --network base-sepolia
 */
const { ethers, upgrades, network } = require("hardhat");
const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");
const {
  resolveAndAssertChain,
  envRolePrefix,
  resolveRoleAddress,
  resolveAllowlist,
  assertDistinctRoles,
} = require("./lib/chainConfig");

const TREASURY_PROVIDER_ID = ethers.keccak256(ethers.toUtf8Bytes("ELEMENTFLOW_TREASURY"));

async function main() {
  const [deployer] = await ethers.getSigners();
  const warnings = [];
  const providerNet = await ethers.provider.getNetwork();

  const config = resolveAndAssertChain({
    networkName: network.name,
    providerChainId: providerNet.chainId,
    allowLocal: true,
    allowPlanned: false,
  });

  const prefix = envRolePrefix(network.name);
  const admin = resolveRoleAddress({
    envKey: `${prefix}_ADMIN_ADDRESS`,
    fallback: deployer.address,
    config,
    warnings,
    label: "admin",
  });
  const aggregator = resolveRoleAddress({
    envKey: `${prefix}_AGGREGATOR_ADDRESS`,
    fallback: deployer.address,
    config,
    warnings,
    label: "aggregator",
  });
  const treasury = resolveRoleAddress({
    envKey: `${prefix}_TREASURY_ADDRESS`,
    fallback: deployer.address,
    config,
    warnings,
    label: "treasury",
  });
  const feeRecipient = resolveRoleAddress({
    envKey: `${prefix}_FEE_RECIPIENT_ADDRESS`,
    fallback: treasury,
    config,
    warnings,
    label: "feeRecipient",
  });

  assertDistinctRoles({ admin, aggregator, treasury, feeRecipient }, config);

  const feeBps = Number(process.env.FEE_BPS ?? config.deployment?.feeBpsDefault ?? 0);
  const orderTtl = Number(process.env.ORDER_TTL ?? config.deployment?.orderTtlDefault ?? 3600);
  const allowlist = resolveAllowlist(config);

  console.log(`\nDeploying ElementFlow v2 to ${config.name} (chainId=${config.chainId})`);
  console.log("  hardhat net  :", network.name);
  console.log("  deployer     :", deployer.address);
  console.log("  admin        :", admin);
  console.log("  aggregator   :", aggregator);
  console.log("  treasury     :", treasury);
  console.log("  feeRecipient :", feeRecipient);
  console.log(`  feeBps       : ${feeBps} / 100000`);
  console.log(`  orderTtl     : ${orderTtl}s`);
  console.log("  allowlist    :", allowlist.length ? allowlist.join(", ") : "(none)");

  const Registry = await ethers.getContractFactory("ProviderRegistry");
  const registry = await upgrades.deployProxy(Registry, [admin], { kind: "uups", timeout: 0 });
  await registry.waitForDeployment();
  console.log("\nProviderRegistry proxy:", await registry.getAddress());

  const Manager = await ethers.getContractFactory("ElementFlowOrderManager");
  const manager = await upgrades.deployProxy(
    Manager,
    [admin, aggregator, treasury, feeRecipient, feeBps, orderTtl],
    { kind: "uups", timeout: 0 }
  );
  await manager.waitForDeployment();
  console.log("OrderManager proxy    :", await manager.getAddress());

  const Pool = await ethers.getContractFactory("TreasuryPool");
  const pool = await upgrades.deployProxy(
    Pool,
    [admin, await manager.getAddress(), TREASURY_PROVIDER_ID],
    { kind: "uups", timeout: 0 }
  );
  await pool.waitForDeployment();
  console.log("TreasuryPool proxy    :", await pool.getAddress());

  const deployerIsAdmin = admin.toLowerCase() === deployer.address.toLowerCase();

  if (deployerIsAdmin) {
    console.log("\nWiring...");
    await (await manager.setProviderRegistry(await registry.getAddress())).wait();
    await (await registry.registerProvider(TREASURY_PROVIDER_ID, await pool.getAddress())).wait();
    await (await manager.setDefaultProviderId(TREASURY_PROVIDER_ID)).wait();
    for (const token of allowlist) {
      await (await manager.setTokenAllowed(token, true)).wait();
      await (await pool.setTokenSupported(token, true)).wait();
      console.log("  allowlisted", token);
    }
    console.log("  done");
  } else {
    console.log("\nAdmin is not the deployer — execute these from the admin/multisig account:");
    console.log(`  orderManager.setProviderRegistry(${await registry.getAddress()})`);
    console.log(`  registry.registerProvider(${TREASURY_PROVIDER_ID}, ${await pool.getAddress()})`);
    console.log(`  orderManager.setDefaultProviderId(${TREASURY_PROVIDER_ID})`);
    for (const token of allowlist) {
      console.log(`  orderManager.setTokenAllowed(${token}, true)`);
      console.log(`  treasuryPool.setTokenSupported(${token}, true)`);
    }
    if (process.env.REQUIRE_WIRED === "1") {
      throw new Error(
        `REQUIRE_WIRED=1 but admin (${admin}) != deployer (${deployer.address}). ` +
          "CI / automated deploys must use the deployer as admin, or wire manually before smoke."
      );
    }
  }

  const info = {
    network: network.name,
    chainId: config.chainId,
    deployedAt: new Date().toISOString(),
    deployer: deployer.address,
    roles: { admin, aggregator, treasury, feeRecipient },
    config: { feeBps, orderTtl, allowlist },
    contracts: {
      orderManager: {
        proxy: await manager.getAddress(),
        implementation: await upgrades.erc1967.getImplementationAddress(await manager.getAddress()),
      },
      providerRegistry: {
        proxy: await registry.getAddress(),
        implementation: await upgrades.erc1967.getImplementationAddress(await registry.getAddress()),
      },
      treasuryPool: {
        proxy: await pool.getAddress(),
        implementation: await upgrades.erc1967.getImplementationAddress(await pool.getAddress()),
        providerId: TREASURY_PROVIDER_ID,
      },
    },
  };

  const dir = path.join(__dirname, "..", "deployments");
  fs.mkdirSync(dir, { recursive: true });
  const stamped = path.join(dir, `${network.name}-${Date.now()}.json`);
  fs.writeFileSync(stamped, JSON.stringify(info, null, 2));
  const latest = path.join(dir, `${config.chainId}.${network.name}.latest.json`);
  fs.writeFileSync(latest, JSON.stringify(info, null, 2));
  console.log("\nDeployment record:", stamped);
  console.log("Latest (commit public addresses):", latest);
  if (!config.__local) {
    console.log(
      `  Next: copy proxy addresses into config/chains/${config.chainId}.*.json contracts{} and open a PR.`
    );
    console.log("\nVerifying on explorer (required step)...");
    // REQUIRE_VERIFY=0 to skip (not recommended). Needs ETHERSCAN_API_KEY for Basescan.
    const requireVerify = process.env.REQUIRE_VERIFY !== "0";
    const verify = spawnSync(
      "npx",
      ["hardhat", "run", "scripts/verify-deployment.js", "--network", network.name],
      {
        cwd: path.join(__dirname, ".."),
        stdio: "inherit",
        env: { ...process.env, DEPLOYMENT_FILE: latest },
      }
    );
    if (verify.status !== 0) {
      const msg =
        `Explorer verification failed. Set ETHERSCAN_API_KEY and re-run:\n` +
        `  DEPLOYMENT_FILE=${latest} npx hardhat run scripts/verify-deployment.js --network ${network.name}`;
      if (requireVerify) throw new Error(msg);
      console.warn(msg);
    }
  }

  if (warnings.length) {
    console.log("\nWARNINGS");
    warnings.forEach((w) => console.log("  -", w));
  }

  console.log("\nPost-deploy checklist:");
  console.log("  1. Confirm explorer verification (Read/Write as Proxy works).");
  console.log("  2. Fund TreasuryPool with on-ramp liquidity (treasuryPool.fund).");
  console.log("  3. Point the backend at the OrderManager proxy address.");
  console.log("  4. Move DEFAULT_ADMIN_ROLE and UPGRADER_ROLE to the governance multisig.");
  console.log("  5. Renounce any roles the deployer still holds.");
  console.log("  6. npx hardhat run scripts/post-deploy-check.js --network " + network.name);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

/**
 * Strongly typed ElementFlow chain configuration loader.
 *
 * Config files live in config/chains/<chainId>.<slug>.json and are keyed by chainId —
 * never by bare address alone (same CREATE address can appear on Base and Base Sepolia).
 */
const fs = require("fs");
const path = require("path");
const { ethers } = require("ethers");

const CHAINS_DIR = path.join(__dirname, "..", "..", "config", "chains");

function listChainFiles() {
  return fs
    .readdirSync(CHAINS_DIR)
    .filter((f) => /^\d+\..+\.json$/.test(f) && f !== "schema.json")
    .map((f) => path.join(CHAINS_DIR, f));
}

function loadAllChains() {
  const byId = new Map();
  for (const file of listChainFiles()) {
    const cfg = JSON.parse(fs.readFileSync(file, "utf8"));
    if (typeof cfg.chainId !== "number") {
      throw new Error(`Invalid chain config (missing chainId): ${file}`);
    }
    if (byId.has(cfg.chainId)) {
      throw new Error(`Duplicate chainId ${cfg.chainId} in ${file}`);
    }
    cfg.__file = file;
    byId.set(cfg.chainId, cfg);
  }
  return byId;
}

function getChainById(chainId) {
  const id = Number(chainId);
  const cfg = loadAllChains().get(id);
  if (!cfg) {
    throw new Error(
      `No config/chains entry for chainId=${id}. Add a file before deploying.`
    );
  }
  return cfg;
}

function getChainByHardhatNetwork(networkName) {
  for (const cfg of loadAllChains().values()) {
    if (cfg.hardhatNetwork === networkName) return cfg;
  }
  throw new Error(
    `No chain config with hardhatNetwork="${networkName}". Local hardhat/localhost are exempt — pass allowLocal.`
  );
}

/**
 * Resolve config for the current Hardhat run and assert provider chainId matches.
 * @param {object} opts
 * @param {string} opts.networkName hardhat network.name
 * @param {bigint|number|string} opts.providerChainId from ethers.provider.getNetwork()
 * @param {boolean} [opts.allowLocal] permit hardhat/localhost without a config file
 * @param {boolean} [opts.allowPlanned] permit status=planned (default false for deploy/upgrade)
 */
function resolveAndAssertChain({
  networkName,
  providerChainId,
  allowLocal = false,
  allowPlanned = false,
}) {
  const local = networkName === "hardhat" || networkName === "localhost";
  if (local && allowLocal) {
    return {
      chainId: Number(providerChainId),
      name: networkName,
      hardhatNetwork: networkName,
      status: "testnet",
      tokens: [],
      contracts: {
        orderManagerProxy: null,
        orderManagerImpl: null,
        providerRegistryProxy: null,
        treasuryPoolProxy: null,
      },
      roles: {},
      deployment: { confirmations: 0, requireDistinctRoles: false, feeBpsDefault: 0, orderTtlDefault: 3600 },
      __local: true,
    };
  }

  const cfg = getChainByHardhatNetwork(networkName);
  const actual = Number(providerChainId);
  if (actual !== cfg.chainId) {
    throw new Error(
      `Chain ID mismatch: hardhat network "${networkName}" expects chainId ${cfg.chainId} ` +
        `but provider reported ${actual}. Refusing to continue (wrong RPC / wrong network).`
    );
  }
  if (cfg.status === "planned" && !allowPlanned) {
    throw new Error(
      `Chain ${cfg.name} (${cfg.chainId}) is status=planned. Complete docs/ADD_CHAIN_CHECKLIST.md ` +
        `and flip status before deploy/upgrade.`
    );
  }
  return cfg;
}

function envRolePrefix(networkName) {
  return networkName.toUpperCase().replace(/-/g, "_");
}

/**
 * Resolve an address from env, optionally falling back.
 * On live chains with requireDistinctRoles, missing env is a hard error (no deployer fallback).
 */
function resolveRoleAddress({
  envKey,
  fallback,
  config,
  warnings,
  label,
}) {
  const raw = process.env[envKey];
  if (raw) return ethers.getAddress(raw);

  const requireDistinct = Boolean(config.deployment?.requireDistinctRoles) || config.status === "live";
  if (requireDistinct) {
    throw new Error(
      `${envKey} is required for ${config.name} (${label}). ` +
        `Live/mainnet deployments must not fall back to the deployer.`
    );
  }
  warnings.push(`${envKey} not set — defaulting to ${fallback} (${label}).`);
  return ethers.getAddress(fallback);
}

/**
 * Token allowlist: prefer config.tokens; if ALLOWED_TOKENS env is set, it must be a
 * subset of config (when config has tokens) or is used as-is for local/empty config.
 */
function resolveAllowlist(config) {
  const fromConfig = (config.tokens || []).map((t) => ethers.getAddress(t.address));
  const envRaw = process.env.ALLOWED_TOKENS ?? "";
  const fromEnv = envRaw
    .split(",")
    .map((t) => t.trim())
    .filter(Boolean)
    .map((t) => ethers.getAddress(t));

  if (!fromEnv.length) return fromConfig;

  if (fromConfig.length) {
    const allowed = new Set(fromConfig.map((a) => a.toLowerCase()));
    const bad = fromEnv.filter((a) => !allowed.has(a.toLowerCase()));
    if (bad.length) {
      throw new Error(
        `ALLOWED_TOKENS contains addresses not in config/chains for chainId=${config.chainId}: ${bad.join(", ")}`
      );
    }
    return fromEnv;
  }
  return fromEnv;
}

/**
 * Upgrade/scan proxy: must match config.contracts.orderManagerProxy unless override.
 */
function resolveProxyAddress(config) {
  const envProxy = process.env.PROXY_ADDRESS;
  const configured = config.contracts?.orderManagerProxy;
  const allowOverride = process.env.ALLOW_PROXY_OVERRIDE === "1";

  if (!envProxy) {
    if (configured) return ethers.getAddress(configured);
    throw new Error(
      `PROXY_ADDRESS is required (or set contracts.orderManagerProxy in ${config.__file || "chain config"}).`
    );
  }

  const proxy = ethers.getAddress(envProxy);
  if (configured && !allowOverride && proxy.toLowerCase() !== configured.toLowerCase()) {
    throw new Error(
      `PROXY_ADDRESS ${proxy} does not match config orderManagerProxy ${configured} ` +
        `for chainId=${config.chainId}. Set ALLOW_PROXY_OVERRIDE=1 only for deliberate exceptions.`
    );
  }
  return proxy;
}

function assertDistinctRoles(roles, config) {
  if (!(config.deployment?.requireDistinctRoles || config.status === "live")) return;
  const entries = Object.entries(roles).filter(([, v]) => v);
  const seen = new Map();
  for (const [name, addr] of entries) {
    const key = addr.toLowerCase();
    if (seen.has(key)) {
      throw new Error(
        `Role addresses must be distinct on ${config.name}: ${seen.get(key)} and ${name} both ${addr}`
      );
    }
    seen.set(key, name);
  }
}

module.exports = {
  CHAINS_DIR,
  loadAllChains,
  getChainById,
  getChainByHardhatNetwork,
  resolveAndAssertChain,
  envRolePrefix,
  resolveRoleAddress,
  resolveAllowlist,
  resolveProxyAddress,
  assertDistinctRoles,
};

/**
 * Post-deploy / post-upgrade checks for a single Hardhat network (one chain only).
 *
 *   npx hardhat run scripts/post-deploy-check.js --network base-sepolia
 *
 * Reads addresses from config/chains and optional deployments/<chainId>.*.latest.json.
 */
const { ethers, network, upgrades } = require("hardhat");
const fs = require("fs");
const path = require("path");
const { resolveAndAssertChain, getChainById } = require("./lib/chainConfig");

const ERC1967_IMPL = "0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc";

function loadLatestDeployment(chainId, networkName) {
  const dir = path.join(__dirname, "..", "deployments");
  const candidates = [
    path.join(dir, `${chainId}.${networkName}.latest.json`),
    path.join(dir, `${chainId}.${networkName}.upgrade.latest.json`),
  ];
  for (const f of candidates) {
    if (fs.existsSync(f)) return { file: f, data: JSON.parse(fs.readFileSync(f, "utf8")) };
  }
  return null;
}

async function implementationOf(address) {
  const raw = await ethers.provider.getStorage(address, ERC1967_IMPL);
  return ethers.getAddress("0x" + raw.slice(26));
}

async function main() {
  const providerNet = await ethers.provider.getNetwork();
  const config = resolveAndAssertChain({
    networkName: network.name,
    providerChainId: providerNet.chainId,
    allowLocal: true,
    allowPlanned: false,
  });

  const latest = loadLatestDeployment(config.chainId || Number(providerNet.chainId), network.name);
  // Prefer the deployment artifact from this run over a stale PROXY_ADDRESS in .env
  // (lab .env.example pins an older OM). Set FORCE_PROXY_ADDRESS=1 to force env.
  const forceEnvProxy = process.env.FORCE_PROXY_ADDRESS === "1";
  const omProxy = forceEnvProxy
    ? process.env.PROXY_ADDRESS ||
      latest?.data?.contracts?.orderManager?.proxy ||
      latest?.data?.proxy ||
      config.contracts?.orderManagerProxy
    : latest?.data?.contracts?.orderManager?.proxy ||
      latest?.data?.proxy ||
      process.env.PROXY_ADDRESS ||
      config.contracts?.orderManagerProxy;
  const registryProxy =
    latest?.data?.contracts?.providerRegistry?.proxy || config.contracts?.providerRegistryProxy;
  const poolProxy =
    latest?.data?.contracts?.treasuryPool?.proxy || config.contracts?.treasuryPoolProxy;

  if (
    !forceEnvProxy &&
    process.env.PROXY_ADDRESS &&
    latest?.data?.contracts?.orderManager?.proxy &&
    ethers.getAddress(process.env.PROXY_ADDRESS) !==
      ethers.getAddress(latest.data.contracts.orderManager.proxy)
  ) {
    console.warn(
      `  NOTE: PROXY_ADDRESS=${process.env.PROXY_ADDRESS} differs from latest deploy ` +
        `${latest.data.contracts.orderManager.proxy} — checking the latest deploy. ` +
        `Set FORCE_PROXY_ADDRESS=1 to force env.`
    );
  }
  if (!omProxy) throw new Error("No OrderManager proxy to check");

  const code = await ethers.provider.getCode(omProxy);
  if (code === "0x") {
    throw new Error(
      `No contract code at ${omProxy} on ${network.name}. ` +
        `Hardhat in-memory chains reset between processes — run deploy then check in the same process, ` +
        `or pass PROXY_ADDRESS for a live network.`
    );
  }

  console.log(`\nPost-deploy check — ${config.name || network.name} chainId=${Number(providerNet.chainId)}`);
  if (latest) console.log("  deployment file:", latest.file);

  const manager = await ethers.getContractAt("ElementFlowOrderManager", omProxy);
  const impl = await implementationOf(omProxy);
  console.log("  orderManager proxy:", omProxy);
  console.log("  orderManager impl :", impl);

  let version = "?";
  try {
    version = await manager.getVersion();
  } catch {
    /* v1 */
  }
  console.log("  version           :", version);
  console.log("  paused            :", await manager.paused());

  const failures = [];

  if (config.contracts?.orderManagerImpl && version.startsWith("2")) {
    // After v2 upgrade, impl should match latest deployment if present
  }
  if (latest?.data?.contracts?.orderManager?.implementation) {
    const expected = ethers.getAddress(latest.data.contracts.orderManager.implementation);
    if (impl.toLowerCase() !== expected.toLowerCase()) {
      failures.push(`impl mismatch: on-chain ${impl} vs record ${expected}`);
    }
  }

  // Token allowlist sync (manager vs pool) when both exist
  if (registryProxy && poolProxy) {
    const pool = await ethers.getContractAt("TreasuryPool", poolProxy);
    console.log("  registry          :", registryProxy);
    console.log("  treasuryPool      :", poolProxy);
    for (const t of config.tokens || []) {
      const allowed = await manager.isTokenAllowed(t.address);
      const supported = await pool.isTokenSupported(t.address);
      console.log(`  token ${t.symbol} managerAllowed=${allowed} poolSupported=${supported}`);
      if (allowed !== supported) {
        failures.push(`allowlist diverge for ${t.symbol}: manager=${allowed} pool=${supported}`);
      }
    }
    const defaultId = await manager.defaultProviderId();
    console.log("  defaultProviderId :", defaultId);
  } else {
    console.log("  registry/pool     : not configured (v1-only or pending wire-up)");
  }

  if (failures.length) {
    console.error("\nFAILURES");
    failures.forEach((f) => console.error("  -", f));
    process.exitCode = 1;
    return;
  }
  console.log("\nPost-deploy check OK");
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

/**
 * Propose an in-place UUPS OrderManager upgrade (implementation + Safe batch).
 *
 * Does NOT execute the upgrade. CI / operators import the Safe Tx Builder JSON
 * and execute with UPGRADER_ROLE (Safe). Proxy address stays unchanged.
 *
 *   npx hardhat run scripts/propose-upgrade.js --network base-sepolia
 *
 * Outputs:
 *   - deployments/<chainId>.<network>.upgrade-propose.*.json
 *   - safe-batches/upgrade-om-<network>.json
 */
const fs = require("fs");
const path = require("path");
const { ethers, upgrades, network } = require("hardhat");
const {
  resolveAndAssertChain,
  resolveProxyAddress,
} = require("./lib/chainConfig");

async function main() {
  const [signer] = await ethers.getSigners();
  const providerNet = await ethers.provider.getNetwork();
  const config = resolveAndAssertChain({
    networkName: network.name,
    providerChainId: providerNet.chainId,
    allowLocal: false,
    allowPlanned: false,
  });

  const proxy = resolveProxyAddress(config);
  const chainId = config.chainId;

  console.log("network     :", network.name, "chainId", chainId);
  console.log("proposer    :", signer.address);
  console.log("proxy       :", proxy);

  const current = await ethers.getContractAt("ElementFlowOrderManager", proxy);
  let currentVersion = "?";
  try {
    currentVersion = await current.getVersion();
  } catch {
    /* v1 or unreachable */
  }
  console.log("getVersion  :", currentVersion);

  const Factory = await ethers.getContractFactory("ElementFlowOrderManager");
  console.log("validateUpgrade...");
  await upgrades.validateUpgrade(proxy, Factory, { kind: "uups" });

  console.log("prepareUpgrade (deploy impl if needed)...");
  const implAddress = await upgrades.prepareUpgrade(proxy, Factory, {
    kind: "uups",
  });
  console.log("implementation:", implAddress);

  // UUPS: upgradeToAndCall on the proxy (called by UPGRADER / Safe).
  const upgradeToData = current.interface.encodeFunctionData("upgradeToAndCall", [
    implAddress,
    "0x",
  ]);

  const safeBatch = {
    version: "1.0",
    chainId: String(chainId),
    createdAt: Date.now(),
    meta: {
      name: `ElementFlow OM upgrade — ${config.name || network.name}`,
      description:
        `UUPS upgradeToAndCall to ${implAddress}. Proxy stays ${proxy}. ` +
        `CI propose only — Safe with UPGRADER_ROLE must execute. Merge ≠ upgrade.`,
      txBuilderVersion: "1.18.0",
      createdFromSafeAddress: config.roles?.multisig || config.roles?.admin || "",
      createdFromOwnerAddress: "",
    },
    transactions: [
      {
        to: proxy,
        value: "0",
        data: upgradeToData,
        contractMethod: {
          inputs: [
            { internalType: "address", name: "newImplementation", type: "address" },
            { internalType: "bytes", name: "data", type: "bytes" },
          ],
          name: "upgradeToAndCall",
          payable: false,
        },
        contractInputsValues: {
          newImplementation: implAddress,
          data: "0x",
        },
      },
    ],
  };

  const outDir = path.join(__dirname, "..", "deployments");
  fs.mkdirSync(outDir, { recursive: true });
  const record = {
    network: network.name,
    chainId,
    proposedAt: new Date().toISOString(),
    proposer: signer.address,
    proxy,
    implementation: implAddress,
    previousVersion: currentVersion,
    note: "Import safe-batches/upgrade-om-*.json into Safe; execute with UPGRADER. Proxy address unchanged.",
  };
  const recordPath = path.join(
    outDir,
    `${chainId}.${network.name}.upgrade-propose.${Date.now()}.json`,
  );
  fs.writeFileSync(recordPath, JSON.stringify(record, null, 2));
  fs.writeFileSync(
    path.join(outDir, `${chainId}.${network.name}.upgrade-propose.latest.json`),
    JSON.stringify(record, null, 2),
  );

  const safeDir = path.join(__dirname, "..", "safe-batches");
  fs.mkdirSync(safeDir, { recursive: true });
  const safePath = path.join(safeDir, `upgrade-om-${network.name}.json`);
  fs.writeFileSync(safePath, JSON.stringify(safeBatch, null, 2));

  console.log("wrote", recordPath);
  console.log("wrote", safePath);
  console.log("NEXT: Safe owners review + execute. Then post-deploy-check + smoke.");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

