/**
 * Computes the `LEGACY_ESCROW` seed required by `scripts/upgrade-v1-to-v2.js`.
 *
 *   PROXY_ADDRESS=0x... FROM_BLOCK=12345678 \
 *     npx hardhat run scripts/scan-legacy-orders.js --network base
 *
 * PROXY_ADDRESS must match config orderManagerProxy unless ALLOW_PROXY_OVERRIDE=1.
 */
const { ethers, network } = require("hardhat");
const {
  resolveAndAssertChain,
  resolveProxyAddress,
} = require("./lib/chainConfig");

const V1_STATUS = { Pending: 0, Completed: 1, Cancelled: 2 };
const ORDER_TYPE = { OnRamp: 0, OffRamp: 1 };
const CHUNK = Number(process.env.LOG_CHUNK ?? 50_000);
if (!Number.isFinite(CHUNK) || CHUNK <= 0) {
  throw new Error(`LOG_CHUNK must be a positive number (got ${process.env.LOG_CHUNK})`);
}

async function main() {
  const providerNet = await ethers.provider.getNetwork();
  const config = resolveAndAssertChain({
    networkName: network.name,
    providerChainId: providerNet.chainId,
    allowLocal: false,
    allowPlanned: false,
  });

  const proxyAddress = resolveProxyAddress(config);
  const fromBlock = Number(process.env.FROM_BLOCK ?? 0);
  const toBlock = Number(process.env.TO_BLOCK ?? (await ethers.provider.getBlockNumber()));

  const v1 = await ethers.getContractAt("OrderManagement", proxyAddress);
  const filter = v1.filters.OrderCreated();

  console.log(
    `Scanning ${proxyAddress} on ${config.name} (chainId=${config.chainId}), blocks ${fromBlock}..${toBlock}`
  );

  const orderIds = new Set();
  for (let start = fromBlock; start <= toBlock; start += CHUNK) {
    const end = Math.min(start + CHUNK - 1, toBlock);
    const logs = await v1.queryFilter(filter, start, end);
    logs.forEach((log) => orderIds.add(log.args.orderId));
    if (logs.length) console.log(`  ${start}..${end}: ${logs.length} orders (total ${orderIds.size})`);
  }

  console.log(`\nFound ${orderIds.size} orders. Reading current status...`);

  const pendingOffRampByToken = new Map();
  const summary = { pendingOffRamp: 0, pendingOnRamp: 0, completed: 0, cancelled: 0 };

  for (const orderId of orderIds) {
    let order;
    try {
      order = await v1.getOrder(orderId);
    } catch (error) {
      throw new Error(
        `Failed to read order ${orderId}; refusing to emit LEGACY_ESCROW. Underlying: ${error.message}`
      );
    }

    const [, , , token, amount, status, orderType] = order;

    if (Number(status) === V1_STATUS.Completed) summary.completed++;
    else if (Number(status) === V1_STATUS.Cancelled) summary.cancelled++;
    else if (Number(orderType) === ORDER_TYPE.OffRamp) {
      summary.pendingOffRamp++;
      const key = ethers.getAddress(token);
      pendingOffRampByToken.set(key, (pendingOffRampByToken.get(key) ?? 0n) + amount);
    } else {
      summary.pendingOnRamp++;
    }
  }

  console.log("\nStatus summary:", summary);
  console.log("\nPending off-ramp escrow by token:");
  for (const [token, amount] of pendingOffRampByToken) {
    const held = await (await ethers.getContractAt("IERC20", token)).balanceOf(proxyAddress);
    console.log(`  ${token}  escrow=${amount}  proxyBalance=${held}`);
    if (held < amount) {
      console.log("    WARNING: the proxy holds less than the pending escrow for this token.");
    }
  }

  const seed = [...pendingOffRampByToken.entries()].map(([t, a]) => `${t}:${a}`).join(",");
  console.log("\nLEGACY_ESCROW=" + (seed || "(none)"));
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

/**
 * Minimal Base Sepolia smoke against a deployment record.
 *
 *   DEPLOYMENT_FILE=deployments/84532.base-sepolia.latest.json \
 *     npx hardhat run scripts/smoke-base-sepolia.js --network base-sepolia
 *
 * Needs deployer key with AGGREGATOR/ORDER_CREATOR roles (true for fresh ephemeral deploy)
 * and ERC20 balance for off-ramp + pool funding. If SMOKE_TOKEN has no faucet mint,
 * on-ramp/off-ramp token legs are skipped with a warning after contract wiring checks.
 */
const { ethers, network } = require("hardhat");
const fs = require("fs");

const ERC20_ABI = [
  "function balanceOf(address) view returns (uint256)",
  "function approve(address,uint256) returns (bool)",
  "function faucet() returns (bool)",
  "function mint(address,uint256)",
  "function decimals() view returns (uint8)",
  "function symbol() view returns (string)",
];

async function main() {
  const file = process.env.DEPLOYMENT_FILE;
  if (!file || !fs.existsSync(file)) throw new Error("DEPLOYMENT_FILE missing");
  const dep = JSON.parse(fs.readFileSync(file, "utf8"));
  console.log(`Smoke on ${network.name} chainId=${dep.chainId}`);

  const [signer] = await ethers.getSigners();
  const manager = await ethers.getContractAt("ElementFlowOrderManager", dep.contracts.orderManager.proxy);
  const registry = await ethers.getContractAt("ProviderRegistry", dep.contracts.providerRegistry.proxy);
  const pool = await ethers.getContractAt("TreasuryPool", dep.contracts.treasuryPool.proxy);

  console.log("orderManager", await manager.getAddress());
  console.log("version", await manager.getVersion());
  console.log("defaultProviderId", await manager.defaultProviderId());
  console.log("pool", await pool.getAddress(), "active?", await registry.isProviderActive(dep.contracts.treasuryPool.providerId));

  const tokenAddr = process.env.SMOKE_TOKEN || (dep.config.allowlist && dep.config.allowlist[0]);
  if (!tokenAddr) {
    console.log("No token configured — wiring-only smoke OK");
    return;
  }

  const token = new ethers.Contract(tokenAddr, ERC20_ABI, signer);
  let symbol = "?";
  try {
    symbol = await token.symbol();
  } catch {
    /* ignore */
  }
  console.log("token", tokenAddr, symbol);

  // Try faucet/mint if available (many test USDC variants expose one).
  for (const fn of ["faucet", "mint"]) {
    try {
      if (fn === "faucet") await (await token.faucet()).wait();
      else await (await token.mint(signer.address, 1_000_000n * 10n ** 6n)).wait();
      console.log("obtained test tokens via", fn);
      break;
    } catch {
      /* try next */
    }
  }

  const bal = await token.balanceOf(signer.address);
  console.log("token balance", bal.toString());
  if (bal === 0n) {
    console.warn("No ERC20 for smoke settlement paths — verified wiring only.");
    return;
  }

  const amount = bal > 1_000_000n ? 1_000_000n : bal / 10n;
  if (amount === 0n) {
    console.warn("Balance too small for smoke amounts");
    return;
  }

  // Fund pool for on-ramp
  await (await token.approve(await pool.getAddress(), amount * 2n)).wait();
  await (await pool.fund(tokenAddr, amount)).wait();
  console.log("funded pool", amount.toString());

  // On-ramp create + settle
  const onMsg = `smoke-on-${Date.now()}`;
  const onTx = await manager.createOrder(signer.address, ethers.ZeroAddress, amount, tokenAddr, 0, onMsg);
  const onRc = await onTx.wait();
  const onCreated = onRc.logs
    .map((l) => {
      try {
        return manager.interface.parseLog(l);
      } catch {
        return null;
      }
    })
    .find((l) => l && l.name === "OrderCreated");
  const onId = onCreated.args.orderId;
  console.log("on-ramp created", onId);
  const userBefore = await token.balanceOf(signer.address);
  const settleOn = await (await manager.settleOrder(onId)).wait();
  const settledEv = settleOn.logs
    .map((l) => {
      try {
        return manager.interface.parseLog(l);
      } catch {
        return null;
      }
    })
    .find((l) => l && l.name === "OrderSettled");
  console.log("on-ramp settled event fields", {
    token: settledEv.args.token,
    requester: settledEv.args.requester,
    netAmount: settledEv.args.netAmount.toString(),
    providerId: settledEv.args.providerId,
  });
  const userAfter = await token.balanceOf(signer.address);
  console.log("user delta", (userAfter - userBefore).toString());

  // Off-ramp create + refund (exercises OrderRefunded rich event)
  await (await token.approve(await manager.getAddress(), amount)).wait();
  const offMsg = `smoke-off-${Date.now()}`;
  const offTx = await manager.createOrder(signer.address, ethers.ZeroAddress, amount, tokenAddr, 1, offMsg);
  const offRc = await offTx.wait();
  const offCreated = offRc.logs
    .map((l) => {
      try {
        return manager.interface.parseLog(l);
      } catch {
        return null;
      }
    })
    .find((l) => l && l.name === "OrderCreated");
  const offId = offCreated.args.orderId;
  const refundRc = await (await manager.refundOrder(offId)).wait();
  const refundEv = refundRc.logs
    .map((l) => {
      try {
        return manager.interface.parseLog(l);
      } catch {
        return null;
      }
    })
    .find((l) => l && l.name === "OrderRefunded");
  console.log("off-ramp refunded event fields", {
    token: refundEv.args.token,
    requester: refundEv.args.requester,
    amount: refundEv.args.amount.toString(),
  });

  console.log("SMOKE OK");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * In-place upgrade of a live v1 `OrderManagement` proxy to `ElementFlowOrderManager` v2.
 *
 * The proxy address does not change, so the backend, the frontend and every pending v1
 * order keep working. Two v1 vulnerabilities are live (permissionless `escrowFunds` /
 * `releaseEscrow` can freeze user escrow forever, and `createOrder` has no access
 * control), which is why this is an upgrade rather than a migration to a new address.
 *
 *   PROXY_ADDRESS=0x... LEGACY_ESCROW=0xTokenA:1000000,0xTokenB:5000000 \
 *     npx hardhat run scripts/upgrade-v1-to-v2.js --network base-sepolia
 *
 * PROXY_ADDRESS must match config/chains/<chainId>.*.json contracts.orderManagerProxy
 * unless ALLOW_PROXY_OVERRIDE=1.
 */
const { ethers, upgrades, network } = require("hardhat");
const fs = require("fs");
const path = require("path");
const {
  resolveAndAssertChain,
  envRolePrefix,
  resolveRoleAddress,
  resolveProxyAddress,
  assertDistinctRoles,
} = require("./lib/chainConfig");

function parseLegacyEscrow(raw) {
  if (!raw) return { tokens: [], amounts: [] };
  const tokens = [];
  const amounts = [];
  for (const entry of raw.split(",").map((e) => e.trim()).filter(Boolean)) {
    const [token, amount] = entry.split(":");
    if (!token || !amount) throw new Error(`Malformed LEGACY_ESCROW entry: "${entry}" (want 0xToken:amount)`);
    tokens.push(ethers.getAddress(token.trim()));
    amounts.push(BigInt(amount.trim()));
  }
  return { tokens, amounts };
}

async function main() {
  const [signer] = await ethers.getSigners();
  const warnings = [];
  const providerNet = await ethers.provider.getNetwork();
  const config = resolveAndAssertChain({
    networkName: network.name,
    providerChainId: providerNet.chainId,
    allowLocal: false,
    allowPlanned: false,
  });

  const proxyAddress = resolveProxyAddress(config);
  const prefix = envRolePrefix(network.name);

  const admin = resolveRoleAddress({
    envKey: `${prefix}_ADMIN_ADDRESS`,
    fallback: signer.address,
    config,
    warnings,
    label: "admin",
  });
  const aggregator = resolveRoleAddress({
    envKey: `${prefix}_AGGREGATOR_ADDRESS`,
    fallback: signer.address,
    config,
    warnings,
    label: "aggregator",
  });
  const feeRecipient = resolveRoleAddress({
    envKey: `${prefix}_FEE_RECIPIENT_ADDRESS`,
    fallback: admin,
    config,
    warnings,
    label: "feeRecipient",
  });
  assertDistinctRoles({ admin, aggregator, feeRecipient }, config);

  const feeBps = Number(process.env.FEE_BPS ?? config.deployment?.feeBpsDefault ?? 0);
  const orderTtl = Number(process.env.ORDER_TTL ?? config.deployment?.orderTtlDefault ?? 3600);
  const { tokens, amounts } = parseLegacyEscrow(process.env.LEGACY_ESCROW);

  const v1 = await ethers.getContractAt("OrderManagement", proxyAddress);
  const currentOwner = await v1.owner();
  const currentTreasury = await v1.treasury();

  console.log(`\nUpgrading ${proxyAddress} on ${config.name} (chainId=${config.chainId})`);
  console.log("  signer          :", signer.address);
  console.log("  current owner   :", currentOwner);
  console.log("  current treasury:", currentTreasury, "(carried over from v1 storage)");
  console.log("  new admin       :", admin);
  console.log("  new aggregator  :", aggregator);
  console.log("  fee recipient   :", feeRecipient);
  console.log(`  feeBps          : ${feeBps} / 100000`);
  console.log(`  orderTtl        : ${orderTtl}s`);
  console.log(
    "  legacy escrow   :",
    tokens.length ? tokens.map((t, i) => `${t}=${amounts[i]}`).join(", ") : "(none)"
  );

  if (currentOwner.toLowerCase() !== signer.address.toLowerCase()) {
    throw new Error(
      `Signer is not the v1 owner. v1 gates upgrades with onlyOwner, so ${currentOwner} must run this.`
    );
  }
  if (!tokens.length) {
    if (process.env.ALLOW_EMPTY_LEGACY_ESCROW !== "1") {
      throw new Error(
        "LEGACY_ESCROW is empty. Run scan-legacy-orders.js first, or set ALLOW_EMPTY_LEGACY_ESCROW=1 " +
          "only if you are sure no v1 off-ramp is still pending."
      );
    }
    console.log(
      "\n  WARNING: ALLOW_EMPTY_LEGACY_ESCROW=1 — proceeding with no seed. " +
        "Only correct if no v1 off-ramp order is still pending."
    );
  }

  const V2 = await ethers.getContractFactory("ElementFlowOrderManager");

  console.log("\nValidating storage layout...");
  await upgrades.validateUpgrade(proxyAddress, V2, { kind: "uups" });
  console.log("  layout is compatible");

  const wasPaused = await v1.paused();
  const v2 = await upgrades.upgradeProxy(proxyAddress, V2, {
    kind: "uups",
    call: {
      fn: "initializeV2",
      args: [admin, aggregator, feeRecipient, feeBps, orderTtl, tokens, amounts],
    },
  });
  await v2.waitForDeployment();

  const implementation = await upgrades.erc1967.getImplementationAddress(proxyAddress);
  console.log("\nUpgrade complete");
  console.log("  proxy         :", proxyAddress, "(unchanged)");
  console.log("  implementation:", implementation);
  console.log("  version       :", await v2.getVersion());
  console.log("  treasury      :", await v2.treasury());
  console.log("  paused        :", await v2.paused(), wasPaused ? "(preserved from v1)" : "");

  if (wasPaused && !(await v2.paused())) {
    throw new Error("Post-upgrade check failed: v1 was paused but v2 is not");
  }

  for (const [i, token] of tokens.entries()) {
    const seeded = await v2.escrowedBalance(token);
    const held = await (await ethers.getContractAt("IERC20", token)).balanceOf(proxyAddress);
    console.log(`  ${token}: escrow=${seeded} held=${held} free=${await v2.availableLiquidity(token)}`);
    if (seeded !== amounts[i]) throw new Error(`escrow seed mismatch for ${token}`);
    if (held < seeded) console.log("    WARNING: held balance is below the seeded escrow.");
  }

  const record = {
    network: network.name,
    chainId: config.chainId,
    upgradedAt: new Date().toISOString(),
    proxy: proxyAddress,
    implementation,
    from: "OrderManagement v1",
    to: "ElementFlowOrderManager v2",
    roles: { admin, aggregator, treasury: currentTreasury, feeRecipient },
    legacyEscrowSeed: tokens.map((t, i) => ({ token: t, amount: amounts[i].toString() })),
  };
  const dir = path.join(__dirname, "..", "deployments");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, `upgrade-${network.name}-${Date.now()}.json`), JSON.stringify(record, null, 2));
  fs.writeFileSync(
    path.join(dir, `${config.chainId}.${network.name}.upgrade.latest.json`),
    JSON.stringify(record, null, 2)
  );

  if (warnings.length) {
    console.log("\nWARNINGS");
    warnings.forEach((w) => console.log("  -", w));
  }

  console.log("\nNext steps:");
  console.log("  1. Allowlist tokens: setTokenAllowed(token, true) — v2 rejects unlisted tokens.");
  console.log("  2. Deploy + register ProviderRegistry and TreasuryPool, then setProviderRegistry.");
  console.log("  3. Drain pending v1 orders with settleLegacyOrder / refundLegacyOrder.");
  console.log("  4. Move DEFAULT_ADMIN_ROLE and UPGRADER_ROLE to the governance multisig.");
  console.log("  5. Update config/chains + run scripts/post-deploy-check.js — this chain only.");
  console.log("  6. Do NOT assume other chains are upgraded because this one succeeded.");
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

/**
 * Verify ElementFlow UUPS implementations + link proxies on the explorer.
 *
 * Etherscan API v2 requires:
 *   - hardhat.config.js etherscan.apiKey as a **single string** (not a per-network map)
 *   - chainid query param (hardhat-verify adds it when apiKey is a string)
 *
 * OpenZeppelin's proxy-verify path still calls getLogs without chainid on some versions,
 * so this script verifies **implementations** via hardhat-verify, then links proxies
 * with the official `verifyproxycontract` action (chainid included).
 *
 *   DEPLOYMENT_FILE=deployments/84532.base-sepolia.latest.json \
 *     npx hardhat run scripts/verify-deployment.js --network base-sepolia
 */
const { run, network, upgrades, ethers } = require("hardhat");
const fs = require("fs");
const path = require("path");
const { resolveAndAssertChain } = require("./lib/chainConfig");

function loadLatestDeployment(chainId, networkName) {
  const dir = path.join(__dirname, "..", "deployments");
  const candidates = [
    path.join(dir, `${chainId}.${networkName}.latest.json`),
    path.join(dir, `${chainId}.${networkName}.upgrade.latest.json`),
  ];
  for (const f of candidates) {
    if (fs.existsSync(f)) return { file: f, data: JSON.parse(fs.readFileSync(f, "utf8")) };
  }
  return null;
}

function isAlreadyVerifiedMessage(msg) {
  return /already verified/i.test(msg) || /already been verified/i.test(msg);
}

async function verifyImplementation(address, label) {
  console.log(`\nVerifying ${label} impl: ${address}`);
  try {
    await run("verify:verify", {
      address,
      constructorArguments: [],
    });
    console.log(`  OK ${label} implementation`);
    return true;
  } catch (error) {
    const msg = error.message || String(error);
    if (isAlreadyVerifiedMessage(msg)) {
      console.log(`  already verified ${label} implementation`);
      return true;
    }
    // Sourcify sometimes returns HTML after Etherscan already succeeded.
    if (/Unexpected token '<'|DOCTYPE/i.test(msg)) {
      console.log(`  OK ${label} implementation (explorer verified; ignoring Sourcify HTML error)`);
      return true;
    }
    console.error(`  FAILED ${label} implementation: ${msg}`);
    return false;
  }
}

/**
 * Link EIP-1967 proxy → implementation on Etherscan/Basescan (API v2).
 */
async function linkProxy(proxy, apiKey, chainId, label) {
  console.log(`\nLinking ${label} proxy: ${proxy}`);
  const url = new URL("https://api.etherscan.io/v2/api");
  url.searchParams.set("chainid", String(chainId));

  const body = new URLSearchParams({
    module: "contract",
    action: "verifyproxycontract",
    address: proxy,
    apikey: apiKey,
  });

  const res = await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body,
  });
  const json = await res.json();
  if (json.status !== "1" && !/already|verified/i.test(String(json.result || json.message))) {
    // Some explorers return GUID in result even when message is NOTOK with pending
    if (!json.result || typeof json.result !== "string") {
      console.error(`  FAILED ${label} proxy link: ${json.message} ${json.result}`);
      return false;
    }
  }

  const guid = json.result;
  console.log(`  submitted proxy link guid=${guid}`);

  // Poll checkproxyverification
  for (let i = 0; i < 12; i++) {
    await new Promise((r) => setTimeout(r, 5000));
    const checkUrl = new URL("https://api.etherscan.io/v2/api");
    checkUrl.searchParams.set("chainid", String(chainId));
    checkUrl.searchParams.set("module", "contract");
    checkUrl.searchParams.set("action", "checkproxyverification");
    checkUrl.searchParams.set("guid", guid);
    checkUrl.searchParams.set("apikey", apiKey);
    const check = await (await fetch(checkUrl)).json();
    const result = String(check.result || "");
    if (check.status === "1" || /successfully|verified|All good/i.test(result)) {
      console.log(`  OK ${label} proxy linked — ${result}`);
      return true;
    }
    if (/fail|error|invalid/i.test(result) && !/Pending/i.test(result)) {
      console.error(`  FAILED ${label} proxy link: ${result}`);
      return false;
    }
    console.log(`  waiting… ${result || check.message}`);
  }
  console.warn(`  WARN ${label} proxy link still pending — check explorer manually`);
  return true; // impl is verified; proxy link often finishes async
}

async function main() {
  if (network.name === "hardhat" || network.name === "localhost") {
    throw new Error("Refuse verify on local in-memory network");
  }

  const providerNet = await ethers.provider.getNetwork();
  const config = resolveAndAssertChain({
    networkName: network.name,
    providerChainId: providerNet.chainId,
    allowLocal: false,
    allowPlanned: true,
  });

  const apiKey = process.env.ETHERSCAN_API_KEY || process.env.BASESCAN_API_KEY;
  if (!apiKey) {
    throw new Error(
      "ETHERSCAN_API_KEY missing. Add it to .env (single Etherscan API v2 key) and re-run.\n" +
        "https://etherscan.io/apidashboard"
    );
  }

  let dep;
  if (process.env.DEPLOYMENT_FILE) {
    dep = JSON.parse(fs.readFileSync(process.env.DEPLOYMENT_FILE, "utf8"));
  } else {
    const latest = loadLatestDeployment(config.chainId, network.name);
    if (!latest?.data) {
      throw new Error(
        `No DEPLOYMENT_FILE and no deployments/${config.chainId}.${network.name}.latest.json`
      );
    }
    dep = latest.data;
  }

  if (Number(dep.chainId) !== Number(config.chainId)) {
    throw new Error(
      `Deployment chainId ${dep.chainId} != network chainId ${config.chainId}`
    );
  }

  console.log(`Verify on ${network.name} chainId=${config.chainId}`);
  console.log(`Artifact deployedAt=${dep.deployedAt || dep.upgradedAt || "?"}`);

  const results = [];
  // Fresh deploy: dep.contracts.{orderManager,providerRegistry,treasuryPool}
  // Upgrade artifact: top-level { proxy, implementation }
  let contracts = dep.contracts || {};
  if (!Object.keys(contracts).length && dep.proxy) {
    contracts = {
      orderManager: {
        proxy: dep.proxy,
        implementation: dep.implementation,
      },
    };
  }
  if (!Object.keys(contracts).length) {
    throw new Error(
      "Deployment artifact has no contracts to verify " +
        `(expected dep.contracts.* or upgrade {proxy,implementation}). File shape: ${Object.keys(dep).join(",")}`
    );
  }

  for (const [name, entry] of Object.entries(contracts)) {
    if (!entry?.proxy) continue;

    let impl = entry.implementation;
    if (!impl) {
      impl = await upgrades.erc1967.getImplementationAddress(entry.proxy);
    }

    const okImpl = await verifyImplementation(impl, name);
    results.push({ name: `${name}.implementation`, address: impl, ok: okImpl });

    // Only link proxy after impl is on the explorer (enables Read/Write as Proxy).
    if (okImpl) {
      const okProxy = await linkProxy(entry.proxy, apiKey, config.chainId, name);
      results.push({ name: `${name}.proxy`, address: entry.proxy, ok: okProxy });
    } else {
      results.push({ name: `${name}.proxy`, address: entry.proxy, ok: false });
    }
  }

  const failed = results.filter((r) => !r.ok);
  console.log("\n--- verify summary ---");
  for (const r of results) {
    console.log(`  ${r.ok ? "OK" : "FAIL"}  ${r.name}  ${r.address}`);
  }

  if (failed.length) {
    throw new Error(
      `${failed.length} verification(s) failed. Re-run:\n` +
        `  DEPLOYMENT_FILE=deployments/${config.chainId}.${network.name}.latest.json \\\n` +
        `    npm run verify:deployment -- --network ${network.name}`
    );
  }

  console.log("\nAll contracts verified / proxies linked.");
  console.log("Confirm Read/Write as Proxy on Basescan.");
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

/**
 * Polls Base Sepolia for ETH on the ephemeral deployer, then deploys v2 + runs a minimal smoke.
 *
 *   node scripts/wait-and-deploy-base-sepolia.js
 *
 * Expects .env / .env.testnet-ephemeral with PRIVATE_KEY and role addresses.
 * Exit 0 = deployed+smoke ok; 2 = still unfunded; 1 = failure.
 */
const path = require("path");
require("dotenv").config({ path: path.join(__dirname, "..", ".env") });
require("dotenv").config({
  path: path.join(__dirname, "..", ".env.testnet-ephemeral"),
  override: true,
});
const { spawnSync } = require("child_process");
const { ethers } = require("ethers");
const fs = require("fs");

// Base Sepolia gas is tiny (~0.00005 ETH for a full v2 stack at ~0.006 gwei).
// CDP drips 0.0001 ETH per claim — one drip is usually enough.
const MIN_ETH = ethers.parseEther(process.env.MIN_DEPLOY_ETH || "0.00012");
const USDC = "0x036CbD53842c5426634e7929541eC2318f3dCF7e";

async function main() {
  const pk = process.env.PRIVATE_KEY;
  if (!pk) throw new Error("PRIVATE_KEY missing");
  const provider = new ethers.JsonRpcProvider(process.env.BASE_SEPOLIA_RPC || "https://sepolia.base.org");
  const wallet = new ethers.Wallet(pk.startsWith("0x") ? pk : `0x${pk}`, provider);
  const bal = await provider.getBalance(wallet.address);
  console.log(`deployer=${wallet.address} balance=${ethers.formatEther(bal)} ETH`);

  if (bal < MIN_ETH) {
    console.log(`Need >= ${ethers.formatEther(MIN_ETH)} ETH on Base Sepolia.`);
    console.log(`Fund via: node scripts/request-base-sepolia-faucet.js`);
    console.log(`Or send ETH to ${wallet.address}`);
    process.exit(2);
  }

  const deploy = spawnSync(
    "npx",
    ["hardhat", "run", "scripts/deploy.js", "--network", "base-sepolia"],
    { cwd: path.join(__dirname, ".."), stdio: "inherit", env: process.env }
  );
  if (deploy.status !== 0) process.exit(deploy.status || 1);

  const dir = path.join(__dirname, "..", "deployments");
  const stable = path.join(dir, "84532.base-sepolia.latest.json");
  if (!fs.existsSync(stable)) {
    throw new Error(`Expected ${stable} from deploy.js`);
  }
  console.log("Using", stable);

  const smoke = spawnSync("npx", ["hardhat", "run", "scripts/smoke-base-sepolia.js", "--network", "base-sepolia"], {
    cwd: path.join(__dirname, ".."),
    stdio: "inherit",
    env: { ...process.env, DEPLOYMENT_FILE: stable, SMOKE_TOKEN: USDC },
  });
  if (smoke.status !== 0) process.exit(smoke.status || 1);

  const check = spawnSync("npx", ["hardhat", "run", "scripts/post-deploy-check.js", "--network", "base-sepolia"], {
    cwd: path.join(__dirname, ".."),
    stdio: "inherit",
    env: process.env,
  });
  if (check.status !== 0) process.exit(check.status || 1);

  const verify = spawnSync("npx", ["hardhat", "run", "scripts/verify-deployment.js", "--network", "base-sepolia"], {
    cwd: path.join(__dirname, ".."),
    stdio: "inherit",
    env: { ...process.env, DEPLOYMENT_FILE: stable },
  });
  process.exit(verify.status || 0);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

const { expect } = require("chai");
const { ethers } = require("hardhat");
const { loadFixture } = require("@nomicfoundation/hardhat-network-helpers");
const { deployStack, OrderType, intentKeyFor, usdc } = require("./helpers");

describe("Multichain order id scoping", function () {
  async function fixture() {
    return deployStack();
  }

  it("binds computeOrderId to chainId and contract address", async function () {
    const ctx = await loadFixture(fixture);
    const token = await ctx.token.getAddress();
    const amount = usdc(100);
    const key = intentKeyFor("multichain-id");
    const chainId = (await ethers.provider.getNetwork()).chainId;

    const onChain = await ctx.manager.computeOrderId(
      ctx.user.address,
      amount,
      token,
      OrderType.OffRamp,
      key
    );

    const expected = ethers.keccak256(
      ethers.AbiCoder.defaultAbiCoder().encode(
        ["uint256", "address", "address", "uint256", "address", "uint8", "bytes32"],
        [chainId, await ctx.manager.getAddress(), ctx.user.address, amount, token, OrderType.OffRamp, key]
      )
    );
    expect(onChain).to.equal(expected);

    // A different chainId yields a different id (replay across chains cannot collide).
    const otherChain = ethers.keccak256(
      ethers.AbiCoder.defaultAbiCoder().encode(
        ["uint256", "address", "address", "uint256", "address", "uint8", "bytes32"],
        [chainId + 1n, await ctx.manager.getAddress(), ctx.user.address, amount, token, OrderType.OffRamp, key]
      )
    );
    expect(otherChain).to.not.equal(onChain);
  });

  it("two manager deployments produce different ids for the same intent", async function () {
    const ctx = await loadFixture(fixture);
    const other = await deployStack();
    const token = await ctx.token.getAddress();
    const amount = usdc(50);
    const key = intentKeyFor("same-intent");

    const a = await ctx.manager.computeOrderId(
      ctx.user.address,
      amount,
      token,
      OrderType.OnRamp,
      key
    );
    const b = await other.manager.computeOrderId(
      ctx.user.address,
      amount,
      await other.token.getAddress(),
      OrderType.OnRamp,
      key
    );
    // Different contract address and/or token address → different id
    expect(a).to.not.equal(b);
  });
});

